import test from 'node:test';import assert from 'node:assert/strict';import {Game,freshProfile} from '../src/domain/game.js';import {durationFor} from '../src/presentation/cinematic.js';
test('ceiling counts consumed draws, guarantees at boundary, resets on jackpot, not stage',()=>{const g=new Game(freshProfile(),0,()=>.99);g.rules.pityLimit=3;for(let n=1;n<=3;n++){g.enqueueDraw();g.tick(g.course.tempo+2*g.machine.reels.stopGap+.01);assert.equal(g.pityCount,n);if(n<3){assert.equal(g.presentation,null);g.tick(1);}}assert.equal(g.presentation.win,true);assert.equal(g.presentation.grade,10);g.tick(durationFor(g.presentation.pattern));assert.equal(g.jackpot.rounds,10);assert.equal(g.pityCount,0);});
test('ordinary pockets and overflow holds do not advance pity; pause freezes it',()=>{const g=new Game(freshProfile(),0,()=>.99);g.enqueueDraw(20);assert.equal(g.pityCount,0);g.pause();g.tick(99);assert.equal(g.pityCount,0);g.resume();g.tick(g.course.tempo+2*g.machine.reels.stopGap+.01);assert.equal(g.pityCount,1);g.award(g.target);g.checkStage();g.selectSkill(g.choices[0].id);assert.equal(g.pityCount,1);});
test('grade weighting selects 4R/6R/10R; edited game never rewards',()=>{for(const [r,grade] of [[.1,4],[.5,6],[.9,10]]){const g=new Game(freshProfile(),0,()=>r);assert.equal(g.drawGrade(),grade);g.debug=true;g.award(1000);g.finish('lost');assert.equal(g.result.tickets,0);assert.equal(g.result.debug,true);}});
